    ResourceSpec("router-dns-timeout", "Resolve intermittent DNS timeouts", "Networking", "troubleshooting guide", "RouterOS", "7.12", "Clients intermittently report DNS_PROBE_FINISHED_BAD_CONFIG after a WAN failover.", "Check the router resolver cache and compare the active WAN route with the upstream DNS route. Capture UDP and TCP port 53 traffic; a stale policy route can send replies through the wrong interface. Flush only the affected cache entries, correct the route rule, and retest with dig against both upstream resolvers.", ("dns", "wan", "failover")),
