    ResourceSpec("wireguard-handshake", "WireGuard handshake has no recent timestamp", "Networking", "troubleshooting guide", "WireGuard", "1.0", "The peer is configured but `latest handshake` remains empty.", "Confirm the endpoint DNS record and UDP listen port, then inspect firewall counters on both peers. A public key mismatch or AllowedIPs route overlap can prevent useful traffic even when UDP reaches the host. Correct the peer key or route and confirm the handshake with wg show.", ("wireguard", "udp", "handshake")),
    ResourceSpec("wireguard-roaming", "WireGuard peer loses connectivity after roaming", "Networking", "configuration manual", "WireGuard", "1.0", "A mobile peer works on Wi-Fi but stops after switching to cellular data.", "Use PersistentKeepalive only for the peer behind NAT, and verify that AllowedIPs includes the intended subnets without stealing the default route. Observe endpoint changes with wg show while the client moves networks. Recheck local firewall state before changing cryptographic keys.", ("wireguard", "nat", "routing")),
